/*
 * A384149  Irregular triangle T(n, k) in which row n gives the
 *          2-densely-aggregated composition of sigma(n).
 * https://oeis.org/A384149
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, tabf
 * Formula:   a(n) is the nth element in the row‑major flattening of the
 *            irregular triangle T(n,k). T(n,k) is the k‑th aggregate sum in
 *            the 2‑densely‑aggregated composition of σ(n) (the sum of all
 *            positive divisors of n). Rows are generated by listing the
 *            divisors of n in increasing order and grouping adjacent...
 * Range:     u8 n <= 87, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   cmp_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/cmp_uint64.h"

/* compare function for qsort with uint64_t arguments */

/* compute the list of aggregate sums for a given row n.
   The result is stored in 'sums' (up to 256 entries) and the number of
   entries is written into 'len'. */
static void row_sums(idx_t n, seq_t *sums, size_t *len)
{
    /* collect all divisors of n */
    uint64_t divisors[256];
    size_t cnt = 0;
    for (idx_t d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            divisors[cnt++] = (uint64_t)d;
            if (d != n / d)
                divisors[cnt++] = (uint64_t)(n / d);
        }
    }

    /* sort divisors ascending */
    qsort(divisors, cnt, sizeof(uint64_t), cmp_uint64);

    /* aggregate adjacent divisors when the next divisor ≤ 2 × previous */
    size_t i = 0;
    *len = 0;
    while (i < cnt) {
        uint64_t sum  = divisors[i];
        uint64_t prev = divisors[i];
        ++i;
        while (i < cnt && divisors[i] <= prev * 2) {
            sum  += divisors[i];
            prev  = divisors[i];
            ++i;
        }
        sums[(*len)++] = (seq_t)sum;
    }
}

/* public routine: return the nth term in the flattened triangle */
seq_t a(idx_t n)
{
    idx_t cumulative = 0;      /* number of entries processed so far */
    for (idx_t row = 1; ; ++row) {
        seq_t   sums[256];
        size_t  len;
        row_sums(row, sums, &len);

        if (cumulative + len >= n) {
            idx_t k = n - cumulative;   /* 1‑based column within this row */
            return sums[k - 1];
        }
        cumulative += len;
    }
}
